(* [comment removed for export] *)
(* [comment removed for export] *)
Definition mss_WB (lo : Z) (sp : word) (R q implb ff fp : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp); (q, q + 312); (R, R + 16); (implb + 12, implb + 16);
   (as_FSB H, as_FSB H + AFS_FLAGS); (fp, fp + 1); (ff, ff + 128); (sh ff, sh ff + 16)]%Z.

Definition mss_segB_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LB' : list block) (LF : list fframe) (R q implb ioc lo shi : Z) (ivp iu ii : Z) (ij7 : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (ff fp : Z),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch (mss_WB lo sp R q implb ff fp) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' R [C8 (wz (q + O_SPC_STORAGE)); C8 (wz q)]
    /\ AStateBlock LB' m' q ioc implb state_init []
    /\ rw_cells bsegs m' implb (SpcHdrCells (mkSPC ivp iu 2 ii) ij7)
    /\ AXStatics2 m'
    /\ fresh_frame H LF 1 ff fp /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi.

(* [comment removed for export] *)
Lemma mss_exit : forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (rax t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' xs3 xs5 xs6 xs7 xs8 xs9 xs11 t40 t48 : word)
    (R q implb ioc spa lo shi ff fp : Z) (ivp iu ii : Z) (LB' : list block) (LF : list fframe)
    (m m0 mx : mem) (lowpad high : list cell) (ja hjunk sh16 ij7 : list byte) (bflag : byte),
  rw_cells bsegs mx spa lowpad -> Z.of_nat (cells_size lowpad) = 8 -> lo <= spa ->
  rw_cells bsegs mx (spa + 8) [CB 16 ja; C8 (Z_to_bv 64 ff); C8 (Z_to_bv 64 ff); C8 t40] ->
  rw_cells bsegs mx (spa + 48) [C8 t48] ->
  rw_cells bsegs mx (spa + 56) high -> Z.of_nat (cells_size high) = bv_unsigned sp + -160 - spa ->
  rw_cells bsegs mx (bv_unsigned sp + -104) (mss_saved s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
  rw_cells bsegs mx ff [CB 120 hjunk; C8 (Z_to_bv 64 fp)] ->
  rw_cells bsegs mx (Z.shiftr ff 3 + 2147450880) [CB 16 sh16] ->
  rw_cells bsegs mx fp [C1 bflag] ->
  stk bsegs mx lo spa -> mem_inv bsegs mx ->
  as_RFS H ((1, ff, fp) :: LF) mx -> fresh_frame H LF 1 ff fp -> ACONST mx -> stack0 mx lo shi ->
  as_RFS H LF m0 ->
  munch (mss_WB lo sp R q implb ff fp) m mx -> wmono bsegs m mx ->
  rw_cells bsegs mx R [C8 (wz (q + O_SPC_STORAGE)); C8 (wz q)] -> aplace R 16 -> fsobj H LF R 16 ->
  AStateBlock LB' mx q ioc implb state_init [] -> fsobj H LF q SZ_SPCI_STATE ->
  rw_cells bsegs mx implb (SpcHdrCells (mkSPC ivp iu 2 ii) ij7) -> aapp implb SZ_SPCI_IMPL -> fsobj H LF implb SZ_SPCI_IMPL ->
  AXStatics2 mx ->
  lo + 176 <= bv_unsigned sp -> spa + 160 <= bv_unsigned sp -> aceil <= lo -> bv_unsigned ra mod 2 = 0 ->
  evt bsegs (mss_segB_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LB' LF R q implb ioc lo shi ivp iu ii ij7 m)
    (MS (mkR rax (Z_to_bv 64 spa) gp tp t0' t1' t2' sp (Z_to_bv 64 spa) a0' a1' a2' a3' a4' a5' a6' a7'
             (Z_to_bv 64 ff) xs3 (Z_to_bv 64 ff) xs5 xs6 xs7 xs8 xs9 (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) xs11 t3' t4' t5' t6')
        F (Z_to_bv 64 AMSS_EXIT) fc None mx (seg_rom bsegs)).
